INSERT INTO DimCustomer (SK_CustomerID, CustomerID, TaxID, Status, LastName, FirstName, MiddleInitial, Gender, Tier, DOB, AddressLine1, AddressLine2, PostalCode, City, StateProv, Country, Phone1, Phone2, Phone3, Email1, Email2, NationalTaxRateDesc, NationalTaxRate, LocalTaxRateDesc, LocalTaxRate, AgencyID, CreditRating, NetWorth, MarketingNameplate, IsCurrent, BatchID, EffectiveDate, EndDate) WITH Customers_Preproc AS (SELECT CXML.C_ID AS CustomerID, TRIM(CXML.C_TAX_ID) AS TaxID, TRIM(UPPER(CASE WHEN NOT CXML.C_GNDR IN ('m', 'f') OR CXML.C_GNDR IS NULL THEN 'u' ELSE CXML.C_GNDR END)) AS Gender, TRY_CAST(CXML.C_TIER AS INT) AS Tier, TRY_CAST(CXML.C_DOB AS DATE) AS DOB, TRIM(CCIN.C_PRIM_EMAIL) AS Email1, TRIM(CCIN.C_ALT_EMAIL) AS Email2, CAST(COALESCE(TRIM(NXML.C_F_NAME), '') AS TEXT) AS FirstName, TRIM(NXML.C_M_NAME) AS MiddleInitial, TRIM(NXML.C_L_NAME) AS LastName, TRIM(ADXML.C_ADLINE1) AS AddressLine1, TRIM(ADXML.C_ADLINE2) AS AddressLine2, TRIM(ADXML.C_ZIPCODE) AS PostalCode, TRIM(ADXML.C_CITY) AS City, TRIM(ADXML.C_STATE_PROV) AS StateProv, TRIM(ADXML.C_CTRY) AS Country, CASE WHEN NOT CP1XML.C_CTRY_CODE IS NULL AND NOT CP1XML.C_AREA_CODE IS NULL AND NOT CP1XML.C_LOCAL IS NULL THEN '+' || CP1XML.C_CTRY_CODE || ' (' || CP1XML.C_AREA_CODE || ') ' || CP1XML.C_LOCAL WHEN CP1XML.C_CTRY_CODE IS NULL AND (NOT CP1XML.C_AREA_CODE IS NULL AND NOT CP1XML.C_LOCAL IS NULL) THEN '(' || CP1XML.C_AREA_CODE || ') ' || CP1XML.C_LOCAL WHEN (CP1XML.C_CTRY_CODE IS NULL AND CP1XML.C_AREA_CODE IS NULL) AND NOT CP1XML.C_LOCAL IS NULL THEN CP1XML.C_LOCAL END AS Phone1_V1, CASE WHEN NOT CP2XML.C_CTRY_CODE IS NULL AND NOT CP2XML.C_AREA_CODE IS NULL AND NOT CP2XML.C_LOCAL IS NULL THEN '+' || CP2XML.C_CTRY_CODE || ' (' || CP2XML.C_AREA_CODE || ') ' || CP2XML.C_LOCAL WHEN CP2XML.C_CTRY_CODE IS NULL AND (NOT CP2XML.C_AREA_CODE IS NULL AND NOT CP2XML.C_LOCAL IS NULL) THEN '(' || CP2XML.C_AREA_CODE || ') ' || CP2XML.C_LOCAL WHEN (CP2XML.C_CTRY_CODE IS NULL AND CP2XML.C_AREA_CODE IS NULL) AND NOT CP2XML.C_LOCAL IS NULL THEN CP2XML.C_LOCAL END AS Phone2_V1, CASE WHEN NOT CP3XML.C_CTRY_CODE IS NULL AND NOT CP3XML.C_AREA_CODE IS NULL AND NOT CP3XML.C_LOCAL IS NULL THEN '+' || CP3XML.C_CTRY_CODE || ' (' || CP3XML.C_AREA_CODE || ') ' || CP3XML.C_LOCAL WHEN CP3XML.C_CTRY_CODE IS NULL AND (NOT CP3XML.C_AREA_CODE IS NULL AND NOT CP3XML.C_LOCAL IS NULL) THEN '(' || CP3XML.C_AREA_CODE || ') ' || CP3XML.C_LOCAL WHEN (CP3XML.C_CTRY_CODE IS NULL AND CP3XML.C_AREA_CODE IS NULL) AND NOT CP3XML.C_LOCAL IS NULL THEN CP3XML.C_LOCAL END AS Phone3_V1, TRIM(TR.TX_NAME) AS NationalTaxRateDesc, TR.TX_RATE AS NationalTaxRate, TRIM(TR2.TX_NAME) AS LocalTaxRateDesc, TR2.TX_RATE AS LocalTaxRate, CP1XML.C_EXT AS C_EXT1, CP2XML.C_EXT AS C_EXT2, CP3XML.C_EXT AS C_EXT3, TRIM(P.AgencyID) AS AgencyID, P.CreditRating, P.NetWorth, CASE WHEN P.NetWorth > 1000000 OR P.Income > 200000 THEN 'HighValue' WHEN P.NumberChildren > 3 OR P.NumberCreditCards > 5 THEN 'Expenses' WHEN P.Age > 45 THEN 'Boomer' WHEN P.Income < 50000 OR P.CreditRating < 600 OR P.NetWorth < 100000 THEN 'MoneyAlert' WHEN P.NumberCars > 3 OR P.NumberCreditCards > 7 THEN 'Spender' WHEN P.Age < 25 AND P.NetWorth > 1000000 THEN 'Inherited' END AS MarketingNameplate, AXML.ActionType, TRY_CAST(AXML.ActionTS AS TIMESTAMP) AS ActionTS FROM Source.CustomerXML AS CXML LEFT JOIN Source.ActionXML AS AXML ON CXML.Action_Id = AXML.Action_Id LEFT JOIN Source.NameXML AS NXML ON CXML.Customer_Id = NXML.Customer_Id LEFT JOIN Source.ContactInfoXML AS CCIN ON CXML.Customer_Id = CCIN.Customer_Id LEFT JOIN Source.AddressXML AS ADXML ON CXML.Customer_Id = ADXML.Customer_Id LEFT JOIN Source.TaxInfoXML AS TXML ON CXML.Customer_Id = TXML.Customer_Id LEFT JOIN Source.TaxRate AS TR ON TXML.C_NAT_TX_ID = TR.TX_ID LEFT JOIN Source.TaxRate AS TR2 ON TXML.C_LCL_TX_ID = TR2.TX_ID LEFT JOIN Source.C_PHONE_1_XML AS CP1XML ON CCIN.ContactInfo_Id = CP1XML.ContactInfo_Id LEFT JOIN Source.C_PHONE_2_XML AS CP2XML ON CCIN.ContactInfo_Id = CP2XML.ContactInfo_Id LEFT JOIN Source.C_PHONE_3_XML AS CP3XML ON CCIN.ContactInfo_Id = CP3XML.ContactInfo_Id LEFT JOIN Source.Prospect AS P ON COALESCE(UPPER(TRIM(NXML.C_F_NAME)), ' ') = COALESCE(UPPER(TRIM(P.FirstName)), ' ') AND COALESCE(UPPER(TRIM(NXML.C_L_NAME)), ' ') = COALESCE(UPPER(TRIM(P.LastName)), ' ') AND COALESCE(UPPER(TRIM(ADXML.C_ADLINE1)), ' ') = COALESCE(UPPER(TRIM(P.AddressLine1)), ' ') AND COALESCE(UPPER(TRIM(ADXML.C_ADLINE2)), ' ') = COALESCE(UPPER(TRIM(P.AddressLine2)), ' ') AND COALESCE(UPPER(TRIM(ADXML.C_ZIPCODE)), ' ') = COALESCE(UPPER(TRIM(P.PostalCode)), ' ')), Customers AS (SELECT *, CASE WHEN NOT C_EXT1 IS NULL THEN Phone1_V1 || C_EXT1 ELSE Phone1_V1 END AS Phone1, CASE WHEN NOT C_EXT2 IS NULL THEN Phone2_V1 || C_EXT2 ELSE Phone2_V1 END AS Phone2, CASE WHEN NOT C_EXT3 IS NULL THEN Phone3_V1 || C_EXT3 ELSE Phone3_V1 END AS Phone3 FROM Customers_Preproc), CustomersNew AS (SELECT *, 'ACTIVE' AS Status FROM Customers WHERE ActionType = 'NEW'), CustomersUpd AS (SELECT * FROM Customers WHERE ActionType = 'UPDCUST'), CustomersInactive AS (SELECT CXML.C_ID AS C_ID, TRY_CAST(AXML.ActionTS AS TIMESTAMP) AS ActionTS FROM Source.CustomerXML AS CXML INNER JOIN Source.ActionXML AS AXML ON CXML.Action_Id = AXML.Action_Id WHERE AXML.ActionType = 'INACT'), CustomersNewAndUpd AS (SELECT CustomerID, TaxID, 'ACTIVE' AS Status, LastName, FirstName, MiddleInitial, Gender, Tier, DOB, AddressLine1, AddressLine2, PostalCode, City, StateProv, Country, Phone1, Phone2, Phone3, Email1, Email2, NationalTaxRateDesc, NationalTaxRate, LocalTaxRateDesc, LocalTaxRate, AgencyID, CreditRating, NetWorth, MarketingNameplate, ActionTS, ActionType FROM CustomersNew UNION ALL SELECT NC.CustomerID, COALESCE(UC.TaxID, NC.TaxID) AS TaxID, NC.Status AS Status, COALESCE(UC.LastName, NC.LastName) AS LastName, COALESCE(UC.FirstName, NC.FirstName) AS FirstName, COALESCE(UC.MiddleInitial, NC.MiddleInitial) AS MiddleInitial, COALESCE(UC.Gender, NC.Gender) AS Gender, COALESCE(UC.Tier, NC.Tier) AS Tier, COALESCE(UC.DOB, NC.DOB) AS DOB, COALESCE(UC.AddressLine1, NC.AddressLine1) AS AddressLine1, COALESCE(UC.AddressLine2, NC.AddressLine2) AS AddressLine2, COALESCE(UC.PostalCode, NC.PostalCode) AS PostalCode, COALESCE(UC.City, NC.City) AS City, COALESCE(UC.StateProv, NC.StateProv) AS StateProv, COALESCE(UC.Country, NC.Country) AS Country, COALESCE(UC.Phone1, NC.Phone1) AS Phone1, COALESCE(UC.Phone2, NC.Phone2) AS Phone2, COALESCE(UC.Phone3, NC.Phone3) AS Phone3, COALESCE(UC.Email1, NC.Email1) AS Email1, COALESCE(UC.Email2, NC.Email2) AS Email2, COALESCE(UC.NationalTaxRateDesc, NC.NationalTaxRateDesc) AS NationalTaxRateDesc, COALESCE(UC.NationalTaxRate, NC.NationalTaxRate) AS NationalTaxRate, COALESCE(UC.LocalTaxRateDesc, NC.LocalTaxRateDesc) AS LocalTaxRateDesc, COALESCE(UC.LocalTaxRate, NC.LocalTaxRate) AS LocalTaxRate, COALESCE(UC.AgencyID, NC.AgencyID) AS AgencyID, COALESCE(UC.CreditRating, NC.CreditRating) AS CreditRating, COALESCE(UC.NetWorth, NC.NetWorth) AS NetWorth, COALESCE(UC.MarketingNameplate, NC.MarketingNameplate) AS MarketingNameplate, UC.ActionTS, UC.ActionType FROM CustomersNew AS NC INNER JOIN CustomersUpd AS UC ON NC.CustomerID = UC.CustomerID), CustomersFinal AS (SELECT * FROM CustomersNewAndUpd UNION ALL SELECT CNU.CustomerID, CNU.TaxID, 'INACTIVE' AS Status, CNU.LastName, CNU.FirstName, CNU.MiddleInitial, CNU.Gender, CNU.Tier, CNU.DOB, CNU.AddressLine1, CNU.AddressLine2, CNU.PostalCode, CNU.City, CNU.StateProv, CNU.Country, CNU.Phone1, CNU.Phone2, CNU.Phone3, CNU.Email1, CNU.Email2, CNU.NationalTaxRateDesc, CNU.NationalTaxRate, CNU.LocalTaxRateDesc, CNU.LocalTaxRate, CNU.AgencyID, CNU.CreditRating, CNU.NetWorth, CNU.MarketingNameplate, CI.ActionTS, 'INACT' AS ActionType FROM CustomersNewAndUpd AS CNU INNER JOIN CustomersInactive AS CI ON CNU.CustomerID = CI.C_ID INNER JOIN (SELECT CustomerID, MAX(ActionTS) AS ActionTSLatestCustomer FROM CustomersNewAndUpd GROUP BY CustomerID) AS LC ON CNU.CustomerID = LC.CustomerID AND CNU.ActionTS = LC.ActionTSLatestCustomer) SELECT CAST(ROW_NUMBER() OVER (ORDER BY CustomerID, ActionTS ASC) AS INT) AS SK_CustomerID, CAST(CustomerID AS INT) AS CustomerID, CAST(TaxID AS TEXT) AS TaxID, CAST(Status AS TEXT) AS Status, CAST(LastName AS TEXT) AS LastName, CAST(FirstName AS TEXT) AS FirstName, CAST(MiddleInitial AS TEXT) AS MiddleInitial, CAST(Gender AS TEXT) AS Gender, CAST(Tier AS INT) AS Tier, CAST(DOB AS DATE) AS DOB, CAST(AddressLine1 AS TEXT) AS AddressLine1, CAST(AddressLine2 AS TEXT) AS AddressLine2, CAST(PostalCode AS TEXT) AS PostalCode, CAST(City AS TEXT) AS City, CAST(StateProv AS TEXT) AS StateProv, CAST(Country AS TEXT) AS Country, CAST(Phone1 AS TEXT) AS Phone1, CAST(Phone2 AS TEXT) AS Phone2, CAST(Phone3 AS TEXT) AS Phone3, CAST(Email1 AS TEXT) AS Email1, CAST(Email2 AS TEXT) AS Email2, CAST(NationalTaxRateDesc AS TEXT) AS NationalTaxRateDesc, CAST(NationalTaxRate AS DECIMAL(6, 5)) AS NationalTaxRate, CAST(LocalTaxRateDesc AS TEXT) AS LocalTaxRateDesc, CAST(LocalTaxRate AS DECIMAL(6, 5)) AS LocalTaxRate, CAST(AgencyID AS TEXT) AS AgencyID, CAST(CreditRating AS INT) AS CreditRating, CAST(NetWorth AS DECIMAL(10, 0)) AS NetWorth, CAST(MarketingNameplate AS TEXT) AS MarketingNameplate, CAST(CASE WHEN LEAD(ActionTS) OVER (PARTITION BY CustomerID ORDER BY ActionTS ASC) IS NULL THEN TRUE ELSE FALSE END AS BOOLEAN) AS IsCurrent, CAST(1 AS INT) AS BatchID, CAST(ActionTS AS DATE) AS EffectiveDate, CAST(COALESCE(LEAD(ActionTS) OVER (PARTITION BY CustomerID ORDER BY ActionTS ASC), CAST('9999-12-31 00:00:00' AS TIMESTAMP)) AS DATE) AS EndDate FROM CustomersFinal ORDER BY CustomerID, ActionTS ASC;
